public class PasswordValidator {
    public static boolean isValid(String pw) {
        if (pw.length() < 8) {
            return false;
        }
        return containsDigit(pw);
    }

    static boolean containsDigit(String s) {
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                return true;
            }
        }
        return false;
    }
}

